from typing import Final

BITS: Final[int] = 8
MASK: Final[int] = 0xFF


def rotl8(x: int, k: int) -> int:
    """Rotate the 8-bit value x left by k bits, wrapping high bits to the low end.

    x is in 0..255 and k is in 0..7. The result is in 0..255.
    """
    return ((x << k) | (x >> (BITS - k))) & MASK


def test_rotl8_zero_shift_is_identity() -> None:
    assert rotl8(0xA5, 0) == 0xA5
    assert rotl8(0x00, 0) == 0x00


def test_rotl8_single_bit_wraps() -> None:
    assert rotl8(0x80, 1) == 0x01
    assert rotl8(0x01, 7) == 0x80


def test_rotl8_known_values() -> None:
    assert rotl8(0x81, 1) == 0x03
    assert rotl8(0xC0, 2) == 0x03
    assert rotl8(0x12, 4) == 0x21


def test_rotl8_all_ones_is_fixed() -> None:
    for k in range(8):
        assert rotl8(0xFF, k) == 0xFF


def test_rotl8_result_in_range() -> None:
    for x in range(256):
        for k in range(8):
            assert 0 <= rotl8(x, k) <= MASK


def test_rotl8_eight_shifts_cycle_back() -> None:
    for x in range(256):
        y = x
        for _ in range(BITS):
            y = rotl8(y, 1)
        assert y == x
